import { auth, currentUser } from "@clerk/nextjs/server";
import { prisma } from "@/db";
import { reconcileExpiredProSubscription } from "@/services/billing/userPlan";
import { upsertUserFromClerk } from "@/repositories/user";

export async function getAuthenticatedUser() {
  const { userId } = await auth();

  if (!userId) {
    return null;
  }

  const clerkUser = await currentUser();

  if (!clerkUser) {
    return null;
  }

  const user = await upsertUserFromClerk(clerkUser);
  await reconcileExpiredProSubscription(user.id);

  return prisma.user.findUnique({
    where: { id: user.id },
    include: {
      subscription: {
        select: {
          status: true,
          currentPeriodEnd: true,
          currentPeriodStart: true,
        },
      },
    },
  });
}

export async function requireAuthenticatedUser() {
  const user = await getAuthenticatedUser();

  if (!user) {
    return null;
  }

  return user;
}
export async function GET() {
  const user = await requireAuthenticatedUser();
  if (!user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  const newsRequests = await listRecentNewsRequests(user.id);
  return NextResponse.json({ newsRequests });
}

export async function POST(request: Request) {
  const user = await requireAuthenticatedUser();
  if (!user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }

  const parsed = requestNewsBodySchema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json(
      { error: "Validation failed", details: z.treeifyError(parsed.error) },
      { status: 400 },
    );
  }

